package com.sun.fortress.compiler.runtimeValues;

/**
 * PROBE 33 (way C, form 2): the payload of the value object ZZ32.  The code
 * generator writes the object's own class, which extends this one; this class
 * extends nothing generated, so it names no library and needs no stub.
 */
public abstract class FZZ32 extends FValue {
    final int val;

    protected FZZ32(int x) { val = x; }
    public String toString() { return String.valueOf(val);}
    public FJavaString asString() { return FJavaString.make(String.valueOf(val));}
    public int getValue() {return val;}
    /**
     * A size read as a value, which the class loader stamps as its text where
     * it lies beyond ZZ32: a ZZ32, or the error of a size out of its range.
     */
    public static FZZ32 makeSize(String s) {
        java.math.BigInteger b = new java.math.BigInteger(s);
        if (b.bitLength() > 31) throw new Error("Not in range for ZZ32: " + s);
        return make(b.intValue());
    }

    /** PROBE 33: the object's class, by the selected library's name for it. */
    static final String OBJECT_CLASS = LibraryNames.numberObjectClass("ZZ32");
    private static final java.lang.invoke.MethodHandle MAKE;
    static {
        try {
            Class<?> c = Class.forName(OBJECT_CLASS, true, FZZ32.class.getClassLoader());
            MAKE = java.lang.invoke.MethodHandles.publicLookup().findStatic(c, "make",
                java.lang.invoke.MethodType.methodType(FZZ32.class, int.class));
        } catch (ReflectiveOperationException e) {
            throw new Error("No class " + OBJECT_CLASS + " for ZZ32", e);
        }
    }

    public static FZZ32 make(int x) {
        try {
            return (FZZ32) MAKE.invokeExact(x);
        } catch (Throwable t) {
            throw new Error(t);
        }
    }
    public static FZZ32 plus(FZZ32 a, FZZ32 b) {return make(a.getValue() + b.getValue());}

}

